 "content": "from collections import Counter, deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] == background or (r, c) in seen:
                continue
            color = g[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and g[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            # Closed rectangular outlines are the frame objects; color their interiors
            # according to whether the outline's side length is odd (7) or even (2).
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            boundary = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                        if y in (r0, r1) or x in (c0, c1)}
            if set(cells) != boundary:
                continue
            fill = 7 if ((r1 - r0 + 1) % 2) else 2
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if g[y][x] == background:
                        g[y][x] = fill
    return g
